{"cards": [{"node_code": "N_9417df42451da639", "definition": "研究铁路行李车与邮政车的设计、构造及运用技术，涵盖行李装卸设施、邮件处理空间布局、通风保温及与旅客列车编组适配的工程内容。", "boundary": "本节点聚焦于客车编组中承担行李与邮件运输功能的车辆。边界在于区分“行李/邮车”与“货车”（前者随旅客列车运行，侧重小件快运与邮政服务；后者为大宗货物运输，归入货车工程）。若内容涉及行李/邮件的物流调度、分拣算法，归入运输管理或物流；若涉及车辆本体结构、内部设施设计，归入本节点。", "includes": ["行李车、邮政车的车体结构、内部货架与装卸装置设计", "行李/邮车的通风、照明、保温及与旅客列车连挂的技术规范"], "excludes": ["大宗货物铁路货车（敞车、棚车等）的技术内容", "行李与邮件的运输组织、调度指挥及物流供应链管理"], "sibling_distinctions": [{"other_code": "N_85381c581a00718b", "rule": "区分依据为功能：本节点关注行李与邮件运输设施；座车关注旅客乘坐空间与座椅布局。"}, {"other_code": "N_73d51593fd05a62e", "rule": "区分依据为编组属性：本节点车辆通常编入旅客列车，服务于客运附属运输；货车编入货物列车，服务于大宗货运。"}], "cross_boundary_rule": "若内容涉及“行包快运”整体流程，侧重车辆设施归本节点，侧重运输组织归运输管理。"}, {"node_code": "N_24c00412ddcac30c", "definition": "研究铁路公务车与瞭望车的设计、构造及运用技术，涵盖办公设施集成、专用通信设备、瞭望平台结构及特殊用途车辆的动力与制动适配。", "boundary": "本节点聚焦于具有特定行政、指挥或观察功能的专用客车。边界在于区分“公务/瞭望车”与“普通座车”（前者具备专用设施或特殊视野要求，后者为通用载客）。若内容涉及公务车内的通信系统独立技术，可关联通信信号；若涉及车辆本体结构、专用设施集成，归入本节点。", "includes": ["公务车、瞭望车的车体结构、专用办公/观察设施设计", "此类车辆的特殊电气配置、通信接口及运用维护技术"], "excludes": ["普通旅客座车、卧车的通用技术内容", "铁路施工、救援等路用特种车辆（非载客公务性质）"], "sibling_distinctions": [{"other_code": "N_85381c581a00718b", "rule": "区分依据为用途：本节点关注行政、指挥或观察专用车辆；座车关注大众化旅客乘坐。"}, {"other_code": "N_fc19e49f91431fd1", "rule": "区分依据为功能属性：本节点车辆虽为专用，但主要服务于人员（公务/观察）；特种路用车辆主要服务于铁路施工、维护等作业。"}], "cross_boundary_rule": "若内容涉及“指挥车”内的调度通信系统，侧重车辆集成归本节点，侧重通信协议归通信信号。"}, {"node_code": "N_4916c0cb61bbebbe", "definition": "研究铁路旅游列车车辆的设计、构造及运用技术，涵盖观光设施、娱乐空间布局、舒适性提升及针对旅游场景的特殊车辆配置。", "boundary": "本节点聚焦于服务于旅游客运的专用或改装客车。边界在于区分“旅游车”与“普通座车/卧车”（前者强调观光、娱乐及旅游服务功能，后者强调基本运输功能）。若内容涉及旅游列车的时刻表、票务，归入运输管理；若涉及车辆内部观光窗、娱乐设施、特殊内饰设计，归入本节点。", "includes": ["旅游客车的观光设施、娱乐空间及特殊内饰设计", "旅游列车的舒适性技术、专用车辆配置及运用维护"], "excludes": ["普通旅客列车（非旅游专用）的通用技术内容", "旅游列车的市场营销、票务管理及旅游服务流程"], "sibling_distinctions": [{"other_code": "N_85381c581a00718b", "rule": "区分依据为服务场景：本节点关注旅游观光与娱乐功能；座车关注常规旅客运输。"}, {"other_code": "N_b09230e0135d65d4", "rule": "区分依据为功能侧重：本节点强调旅游体验与设施；卧车强调睡眠休息功能。"}], "cross_boundary_rule": "若内容涉及“旅游专列”整体运营，侧重车辆设施归本节点，侧重运营组织归运输管理。"}]}
